#ifndef FE2_STATUS_STATUS_TABLES_H
#define FE2_STATUS_STATUS_TABLES_H

/* Native status tables (generated by tools/status_tables_c.py). Arrays that the
 * original indexes past their end include the reachable following data. */
#include <stdint.h>

typedef enum fe2_contract_spawn {
    FE2_CONTRACT_SPAWN_NONE,
    FE2_CONTRACT_SPAWN_ONE,       /* one object, mode 1 */
    FE2_CONTRACT_SPAWN_TWO,       /* two objects, mode 3 */
    FE2_CONTRACT_SPAWN_THREE,     /* three objects, mode 2 */
    FE2_CONTRACT_SPAWN_MODE_FOUR  /* one object, mode 4 */
} fe2_contract_spawn;

/* Contract kinds may create objects (pirates, police...) when random <= chance. */
typedef struct fe2_contract_chance {
    uint16_t chance;
    fe2_contract_spawn spawn;
} fe2_contract_chance;

/* Frontier body copied for mission targets (status_object_template.txt). */
extern const uint8_t fe2_status_object_template[0x11e];
/* Fitted-equipment text by bit; bits 19..31 run on into the next tables. */
extern const uint16_t fe2_status_equipment_text[32];
/* Installed-item text by item class (bits 3..6); classes 11..15 run on. */
extern const uint16_t fe2_status_installed_text[16];
/* Panel widgets for the list pages and the status text directory. */
extern const uint8_t fe2_status_widget_bytes[0x110];
extern const uint8_t *fe2_status_text_bytes;
/* Descending thresholds: criminal record (Fugitive..Offender), Elite rating. */
extern const uint32_t fe2_status_criminal_thresholds[4];
extern const uint32_t fe2_status_combat_thresholds[9];
/* Page header sprite words, read at byte offset = page number. */
extern const uint8_t fe2_status_page_sprite_bytes[17];
/* Fuel tank capacity (high byte of the tank word) by drive class. */
extern const uint8_t fe2_status_fuel_capacity[0x7c];
/* Cargo canister object subtype by cargo type. */
extern const uint8_t fe2_status_cargo_subtypes[31];
/* Military rank bounds: [0] is the top rank's ceiling, then the descending
 * floors of ranks 12..0. */
extern const uint16_t fe2_status_rank_bounds[14];
/* Signed rank changes for military passengers, federal [0..3], imperial [3..6]. */
extern const int8_t fe2_status_rank_adjustments[7];
/* Mission target model by target class, mission title by type. */
extern const uint16_t fe2_status_contract_text[8];
extern const uint16_t fe2_status_mission_text[7];
/* Mission authority (0x36 federal, 0x26 imperial) and permit by type. */
extern const uint8_t fe2_status_mission_authority[7];
extern const int8_t fe2_status_mission_permit[7];
extern const fe2_contract_chance fe2_status_contract_chances[16];

#endif
